script:
frappe.ui.form.on("NMI Payment Transaction", {
    refresh(frm) {
        const status = frm.doc.status;
        const void_status =
            frm.doc.void_status || "Not Requested";

        const refund_status =
            frm.doc.refund_status || "Not Requested";

        // -------------------------------------------------
        // VOID BUTTON
        // -------------------------------------------------
        const can_void =
            status === "ERPNext Completed" &&
            frm.doc.nmi_transaction_id &&
            void_status !== "Approved" &&
            void_status !== "Processing" &&
            refund_status !== "Approved";

        if (can_void) {
            frm.add_custom_button(
                __("Void Payment"),
                () => {
                    frappe.confirm(
                        __("Are you sure you want to void this NMI payment?"),
                        async () => {
                            try {
                                frappe.dom.freeze(
                                    __("Voiding payment with NMI...")
                                );

                                const response = await frappe.call({
                                    method:
                                        "custom_erp.nmi.api.void_payment",
                                    args: {
                                        transaction_name:
                                            frm.doc.name
                                    }
                                });

                                const data = response.message;

                                if (
                                    data &&
                                    data.void_status === "Approved"
                                ) {
                                    await frm.reload_doc();

                                    frappe.msgprint({
                                        title: __("Void Successful"),
                                        indicator: "green",
                                        message:
                                            __("Payment voided successfully.") +
                                            "<br><br>" +
                                            __("Response Code: ") +
                                            (data.response_code || "") +
                                            "<br>" +
                                            __("Message: ") +
                                            (data.response_message || "")
                                    });

                                    return;
                                }

                                await frm.reload_doc();

                                frappe.msgprint({
                                    title: __("Void Failed"),
                                    indicator: "red",
                                    message:
                                        __("NMI did not approve the void request.")
                                });

                            } catch (error) {
                                console.error(
                                    "NMI Void Error:",
                                    error
                                );

                                frappe.msgprint({
                                    title: __("Void Failed"),
                                    indicator: "red",
                                    message:
                                        error.message ||
                                        __("Unable to void NMI payment.")
                                });

                                await frm.reload_doc();

                            } finally {
                                frappe.dom.unfreeze();
                            }
                        }
                    );
                },
                __("NMI")
            );
        }

        // -------------------------------------------------
        // REFUND BUTTON
        // -------------------------------------------------
        const can_refund =
                    status === "ERPNext Completed" &&
                    frm.doc.nmi_transaction_id &&
                    void_status !== "Approved" &&
                    refund_status !== "Processing" &&
                    refund_status !== "Approved";

        if (can_refund) {
            frm.add_custom_button(
                __("Refund Payment"),
                () => {
                    show_refund_dialog(frm);
                },
                __("NMI")
            );
        }
    }
});


function show_refund_dialog(frm) {

    const original_amount = flt(frm.doc.amount);

    const dialog = new frappe.ui.Dialog({
        title: __("Refund NMI Payment"),

        fields: [
            {
                fieldname: "original_amount",
                label: __("Original Payment Amount"),
                fieldtype: "Currency",
                default: original_amount,
                read_only: 1
            },
            {
                fieldname: "refund_amount",
                label: __("Refund Amount"),
                fieldtype: "Currency",
                reqd: 1,
                default: original_amount
            }
        ],

        primary_action_label: __("Refund"),

        primary_action: async (values) => {

            const refund_amount =
                flt(values.refund_amount);

            // ---------------------------------------------
            // CLIENT VALIDATION
            // ---------------------------------------------
            if (refund_amount <= 0) {
                frappe.msgprint(
                    __("Refund amount must be greater than zero.")
                );
                return;
            }

            if (refund_amount > original_amount) {
                frappe.msgprint(
                    __("Refund amount cannot exceed the original payment amount.")
                );
                return;
            }

            dialog.hide();

            frappe.confirm(
                __(
                    "Are you sure you want to refund {0}?",
                    [format_currency(
                        refund_amount,
                        frm.doc.currency
                    )]
                ),

                async () => {

                    try {
                        frappe.dom.freeze(
                            __("Processing refund with NMI...")
                        );

                        const response =
                            await frappe.call({
                                method:
                                    "custom_erp.nmi.api.refund_payment",

                                args: {
                                    transaction_name:
                                        frm.doc.name,

                                    amount:
                                        refund_amount
                                }
                            });

                        const data =
                            response.message;

                        if (
                            data &&
                            data.refund_status ===
                                "Approved"
                        ) {
                            await frm.reload_doc();

                            frappe.msgprint({
                                title:
                                    __("Refund Successful"),

                                indicator:
                                    "green",

                                message:
                                    __("Refund processed successfully.") +
                                    "<br><br>" +
                                    __("Refund Amount: ") +
                                    format_currency(
                                        data.refund_amount,
                                        frm.doc.currency
                                    ) +
                                    "<br>" +
                                    __("Response Code: ") +
                                    (data.response_code || "") +
                                    "<br>" +
                                    __("Message: ") +
                                    (data.response_message || "")
                            });

                            return;
                        }

                        await frm.reload_doc();

                        frappe.msgprint({
                            title:
                                __("Refund Failed"),

                            indicator:
                                "red",

                            message:
                                __("NMI did not approve the refund request.") +
                                "<br><br>" +
                                __("Status: ") +
                                (data?.refund_status || "") +
                                "<br>" +
                                __("Message: ") +
                                (data?.response_message || "")
                        });

                    } catch (error) {

                        console.error(
                            "NMI Refund Error:",
                            error
                        );

                        frappe.msgprint({
                            title:
                                __("Refund Failed"),

                            indicator:
                                "red",

                            message:
                                error.message ||
                                __("Unable to process NMI refund.")
                        });

                        await frm.reload_doc();

                    } finally {

                        frappe.dom.unfreeze();
                    }
                }
            );
        }
    });

    dialog.show();
}
